/* Generated by .ref/tools/gen_curves.py from per-frame measurements of the reference.
 * Each curve is [firstFrame, values...]: one value per frame, smoothed; sample with curve(). */
export type Curve = { f0: number; v: number[] };
/** Value at a (fractional) frame, clamped to the ends, linear between frames. */
export function curve(c: Curve, f: number): number {
  const i = f - c.f0;
  if (i <= 0) return c.v[0]!;
  if (i >= c.v.length - 1) return c.v[c.v.length - 1]!;
  const k = Math.floor(i);
  return c.v[k]! + (c.v[k + 1]! - c.v[k]!) * (i - k);
}

